import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;

@Service
public class ReportingService {
    private static final String EMPLOYEE_SCOPE="""
        (:global=true or e.keycloak_subject=:subject or exists(select 1 from company_membership_scopes s
        join company_memberships m on m.company_id=s.company_id and m.keycloak_subject=s.keycloak_subject
        where s.company_id=e.company_id and s.keycloak_subject=:subject and m.status='ACTIVE' and (
          (s.scope_type='SELF' and s.scope_id=e.id) or
          (s.scope_type='TEAM' and (s.scope_id=e.id or s.scope_id=e.manager_employee_id)) or
          (s.scope_type='DEPARTMENT' and s.scope_id=e.department_id) or
          (s.scope_type='BRANCH' and s.scope_id=e.branch_id))))
        """;
    private static final String PROJECT_SCOPE="""
        (:global=true or owner.keycloak_subject=:subject or exists(select 1 from pm_project_members pm
        join employees me on me.id=pm.employee_id and me.company_id=pm.company_id
        where pm.company_id=p.company_id and pm.project_id=p.id and me.keycloak_subject=:subject)
        or exists(select 1 from company_membership_scopes s join company_memberships m
        on m.company_id=s.company_id and m.keycloak_subject=s.keycloak_subject
        where s.company_id=p.company_id and s.keycloak_subject=:subject and m.status='ACTIVE' and (
          (s.scope_type='PROJECT' and s.scope_id=p.id) or
          (s.scope_type='DEPARTMENT' and s.scope_id=p.department_id) or
          (s.scope_type='BRANCH' and s.scope_id=d.branch_id))))
        """;
    private static final String FINANCE_SCOPE="""
        (:global=true or exists(select 1 from company_membership_scopes s join company_memberships m
        on m.company_id=s.company_id and m.keycloak_subject=s.keycloak_subject
        where s.company_id=f.company_id and s.keycloak_subject=:subject and m.status='ACTIVE' and (
          (s.scope_type='DEPARTMENT' and s.scope_id=f.department_id) or
          (s.scope_type='PROJECT' and s.scope_id=f.project_id))))
        """;
    private final JdbcClient jdbc;
    private final NamedParameterJdbcTemplate named;
    private final ReportingAccess access;
    private final AuditService audit;
    private final ObjectMapper json;

    public ReportingService(JdbcClient jdbc,NamedParameterJdbcTemplate named,ReportingAccess access,AuditService audit,ObjectMapper json){this.jdbc=jdbc;this.named=named;this.access=access;this.audit=audit;this.json=json;}

    public ExecutiveSummary summary(UUID companyId,Authentication authentication){return summaryForPeriod(companyId,authentication,LocalDate.now().withDayOfYear(1),LocalDate.now());}
    private ExecutiveSummary summaryForPeriod(UUID companyId,Authentication authentication,LocalDate periodStart,LocalDate periodEnd){Map<String,Object>p=params(companyId,authentication,"reporting.read");String currency=jdbc.sql("select base_currency from companies where id=:id").param("id",companyId.toString()).query(String.class).optional().orElseThrow(()->notFound("Company not found")).trim();p.put("currency",currency);p.put("periodStart",periodStart);p.put("periodEnd",periodEnd);long employees=count("select count(*) from employees e where e.company_id=:companyId and e.employment_status='ACTIVE' and "+EMPLOYEE_SCOPE,p);long projects=count("select count(*) from pm_projects p left join employees owner on owner.id=p.owner_employee_id left join departments d on d.id=p.department_id where p.company_id=:companyId and p.status in ('PLANNED','ACTIVE','ON_HOLD') and "+PROJECT_SCOPE,p);long overdue=count("""
        select count(*) from pm_tasks t join pm_workflow_statuses ws on ws.id=t.status_id
        left join employees assignee on assignee.id=t.assignee_employee_id
        left join employees supervisor on supervisor.id=t.supervisor_employee_id
        left join pm_projects p on p.id=t.project_id left join employees owner on owner.id=p.owner_employee_id
        left join departments d on d.id=coalesce(t.department_id,p.department_id)
        where t.company_id=:companyId and ws.is_done=false and t.due_date<current_date and (
          :global=true or assignee.keycloak_subject=:subject or supervisor.keycloak_subject=:subject or owner.keycloak_subject=:subject
          or exists(select 1 from pm_project_members pm join employees me on me.id=pm.employee_id where pm.project_id=t.project_id and me.keycloak_subject=:subject)
          or exists(select 1 from company_membership_scopes s join company_memberships m on m.company_id=s.company_id and m.keycloak_subject=s.keycloak_subject
            where s.company_id=t.company_id and s.keycloak_subject=:subject and m.status='ACTIVE' and ((s.scope_type='PROJECT' and s.scope_id=t.project_id) or (s.scope_type='DEPARTMENT' and s.scope_id=coalesce(t.department_id,p.department_id)) or (s.scope_type='BRANCH' and s.scope_id=d.branch_id))))
        """,p);Map<String,Object>money=one("select coalesce(sum(case when f.transaction_type='RECEIPT' then f.amount else 0 end),0) revenue,coalesce(sum(case when f.transaction_type='PAYMENT' then f.amount else 0 end),0) expenses from finance_cash_transactions f where f.company_id=:companyId and f.currency=:currency and f.status='POSTED' and f.occurred_on between :periodStart and :periodEnd and "+FINANCE_SCOPE,p);BigDecimal revenue=decimal(money.get("revenue")),expenses=decimal(money.get("expenses"));BigDecimal pipeline=decimal(one("""
        select coalesce(sum(o.value*o.probability/100.0),0) value from crm_opportunities o
        join crm_pipeline_stages st on st.id=o.stage_id left join employees e on e.id=o.owner_employee_id
        left join departments d on d.id=e.department_id where o.company_id=:companyId and o.currency=:currency and st.is_won=false and st.is_lost=false and
        (:global=true or e.keycloak_subject=:subject or exists(select 1 from company_membership_scopes s join company_memberships m on m.company_id=s.company_id and m.keycloak_subject=s.keycloak_subject where s.company_id=o.company_id and s.keycloak_subject=:subject and m.status='ACTIVE' and ((s.scope_type='DEPARTMENT' and s.scope_id=e.department_id) or (s.scope_type='BRANCH' and s.scope_id=d.branch_id))))
        """,p).get("value"));BigDecimal receivables=decimal(one("select coalesce(sum(f.total_amount-f.paid_amount),0) value from finance_invoices f where f.company_id=:companyId and f.currency=:currency and f.direction='RECEIVABLE' and f.due_date<current_date and f.status not in ('PAID','VOID') and "+FINANCE_SCOPE,p).get("value"));long approvals=count("""
        select count(*) from workplace_approval_requests a where a.company_id=:companyId and a.status='PENDING' and
        (:global=true or a.requester_subject=:subject or exists(select 1 from workplace_approval_steps s where s.approval_request_id=a.id and s.approver_subject=:subject and s.status='PENDING') or exists(select 1 from company_membership_scopes cs join company_memberships m on m.company_id=cs.company_id and m.keycloak_subject=cs.keycloak_subject where cs.company_id=a.company_id and cs.keycloak_subject=:subject and m.status='ACTIVE' and ((cs.scope_type='DEPARTMENT' and cs.scope_id=a.department_id) or (cs.scope_type='PROJECT' and cs.scope_id=a.project_id))))
        """,p);long lowStock=Boolean.TRUE.equals(p.get("global"))?count("select count(*) from ops_inventory_items i where i.company_id=:companyId and i.active=true and coalesce((select sum(s.on_hand-s.committed) from ops_stock_levels s where s.company_id=i.company_id and s.inventory_item_id=i.id),0)<=i.min_stock",p):0;long atRisk=count("select count(*) from strategic_objectives o where o.company_id=:companyId and o.status='AT_RISK' and "+OBJECTIVE_SCOPE,p);return new ExecutiveSummary(currency,employees,projects,overdue,revenue,expenses,revenue.subtract(expenses),pipeline,receivables,approvals,lowStock,atRisk);}

    public List<TrendPoint> trends(UUID companyId,Authentication authentication){Map<String,Object>p=params(companyId,authentication,"reporting.read");String currency=jdbc.sql("select base_currency from companies where id=:id").param("id",companyId.toString()).query(String.class).single().trim();p.put("currency",currency);Map<String,TrendPoint>result=new LinkedHashMap<>();for(int i=5;i>=0;i--){String month=YearMonth.now().minusMonths(i).toString();result.put(month,new TrendPoint(month,BigDecimal.ZERO,BigDecimal.ZERO,0));}for(Map<String,Object>row:rows("select to_char(date_trunc('month',f.occurred_on),'YYYY-MM') period,coalesce(sum(case when f.transaction_type='RECEIPT' then f.amount else 0 end),0) revenue,coalesce(sum(case when f.transaction_type='PAYMENT' then f.amount else 0 end),0) expenses from finance_cash_transactions f where f.company_id=:companyId and f.currency=:currency and f.status='POSTED' and f.occurred_on>=date_trunc('month',current_date)-interval '5 months' and "+FINANCE_SCOPE+" group by date_trunc('month',f.occurred_on) order by 1",p)){String period=text(row.get("period"));TrendPoint old=result.get(period);if(old!=null)result.put(period,new TrendPoint(period,decimal(row.get("revenue")),decimal(row.get("expenses")),old.completedTasks()));}for(Map<String,Object>row:rows("""
        select to_char(date_trunc('month',t.updated_at),'YYYY-MM') period,count(*) completed from pm_tasks t
        join pm_workflow_statuses ws on ws.id=t.status_id left join employees assignee on assignee.id=t.assignee_employee_id
        left join employees supervisor on supervisor.id=t.supervisor_employee_id left join pm_projects p on p.id=t.project_id
        left join employees owner on owner.id=p.owner_employee_id left join departments d on d.id=coalesce(t.department_id,p.department_id)
        where t.company_id=:companyId and ws.is_done=true and t.updated_at>=date_trunc('month',current_date)-interval '5 months' and
        (:global=true or assignee.keycloak_subject=:subject or supervisor.keycloak_subject=:subject or owner.keycloak_subject=:subject or exists(select 1 from company_membership_scopes s join company_memberships m on m.company_id=s.company_id and m.keycloak_subject=s.keycloak_subject where s.company_id=t.company_id and s.keycloak_subject=:subject and m.status='ACTIVE' and ((s.scope_type='PROJECT' and s.scope_id=t.project_id) or (s.scope_type='DEPARTMENT' and s.scope_id=coalesce(t.department_id,p.department_id)) or (s.scope_type='BRANCH' and s.scope_id=d.branch_id)))) group by date_trunc('month',t.updated_at) order by 1
        """,p)){String period=text(row.get("period"));TrendPoint old=result.get(period);if(old!=null)result.put(period,new TrendPoint(period,old.revenue(),old.expenses(),number(row.get("completed"))));}return new ArrayList<>(result.values());}

    public List<Map<String,Object>> projectHealth(UUID companyId,Authentication authentication){Map<String,Object>p=params(companyId,authentication,"reporting.read");return rows("select p.id,p.code,p.name,p.status,p.progress_percent,p.risk_level,p.ends_on,d.name department_name,(select count(*) from pm_tasks t join pm_workflow_statuses s on s.id=t.status_id where t.project_id=p.id and s.is_done=false and t.due_date<current_date) overdue_tasks from pm_projects p left join employees owner on owner.id=p.owner_employee_id left join departments d on d.id=p.department_id where p.company_id=:companyId and "+PROJECT_SCOPE+" order by case p.risk_level when 'CRITICAL' then 0 when 'HIGH' then 1 when 'MEDIUM' then 2 else 3 end,p.ends_on nulls last limit 30",p);}

    private static final String OBJECTIVE_SCOPE="""
        (:global=true or o.owner_subject=:subject or exists(select 1 from company_membership_scopes s
        join company_memberships m on m.company_id=s.company_id and m.keycloak_subject=s.keycloak_subject
        where s.company_id=o.company_id and s.keycloak_subject=:subject and m.status='ACTIVE' and
        ((o.scope_type='DEPARTMENT' and s.scope_type='DEPARTMENT' and s.scope_id=o.scope_id) or
         (o.scope_type='PROJECT' and s.scope_type='PROJECT' and s.scope_id=o.scope_id))))
        """;
    public List<Map<String,Object>> objectives(UUID companyId,Authentication authentication){return rows("select o.id,o.code,o.title,o.description,o.scope_type,o.scope_id,o.owner_subject,o.start_date,o.end_date,o.status,o.progress_percent,o.updated_at,(select count(*) from strategic_key_results k where k.objective_id=o.id) key_result_count from strategic_objectives o where o.company_id=:companyId and "+OBJECTIVE_SCOPE+" order by case o.status when 'AT_RISK' then 0 when 'ACTIVE' then 1 else 2 end,o.end_date",params(companyId,authentication,"strategy.read"));}
    public List<Map<String,Object>> keyResults(UUID companyId,UUID objectiveId,Authentication authentication){Map<String,Object>o=objective(companyId,objectiveId,authentication,"strategy.read");return rows("select id,code,title,metric_type,baseline_value,target_value,current_value,unit,weight,status,updated_at from strategic_key_results where company_id=:companyId and objective_id=:objective order by code",map(companyId,"objective",objectiveId));}
    @Transactional public CreatedResource createObjective(UUID companyId,ObjectiveRequest request,Authentication authentication){if(request.endDate().isBefore(request.startDate()))bad("Objective end date must be on or after start date");if(!access.canAccessScope(authentication,companyId,request.scopeType(),request.scopeId(),"strategy.write"))forbidden();validateScope(companyId,request.scopeType(),request.scopeId());activeMember(companyId,request.ownerSubject());UUID id=UUID.randomUUID();jdbc.sql("insert into strategic_objectives(id,company_id,code,title,description,scope_type,scope_id,owner_subject,start_date,end_date,created_by_subject) values(:id,:companyId,:code,:title,:description,:scopeType,:scopeId,:owner,:start,:end,:actor)").param("id",id.toString()).param("companyId",companyId.toString()).param("code",request.code()).param("title",request.title()).param("description",blank(request.description())).param("scopeType",request.scopeType()).param("scopeId",request.scopeId().toString()).param("owner",request.ownerSubject()).param("start",request.startDate()).param("end",request.endDate()).param("actor",authentication.getName()).update();for(KeyResultRequest key:request.keyResults()){if(key.targetValue().compareTo(key.baselineValue())==0)bad("Key result target must differ from baseline");jdbc.sql("insert into strategic_key_results(id,company_id,objective_id,code,title,metric_type,baseline_value,target_value,current_value,unit,weight,updated_by_subject) values(:id,:companyId,:objective,:code,:title,:type,:baseline,:target,:current,:unit,:weight,:actor)").param("id",UUID.randomUUID().toString()).param("companyId",companyId.toString()).param("objective",id.toString()).param("code",key.code()).param("title",key.title()).param("type",key.metricType()).param("baseline",key.baselineValue()).param("target",key.targetValue()).param("current",key.currentValue()).param("unit",blank(key.unit())).param("weight",key.weight()).param("actor",authentication.getName()).update();}recompute(id);audit.write(companyId,authentication.getName(),"STRATEGIC_OBJECTIVE_CREATED","STRATEGIC_OBJECTIVE",id.toString(),"{}");return new CreatedResource(id,"DRAFT");}
    @Transactional public CreatedResource updateProgress(UUID companyId,UUID keyResultId,ProgressRequest request,Authentication authentication){Map<String,Object>k=one("select k.objective_id,o.scope_type,o.scope_id,o.owner_subject from strategic_key_results k join strategic_objectives o on o.id=k.objective_id where k.company_id=:companyId and k.id=:id for update",map(companyId,"id",keyResultId));ensureScope(k,companyId,authentication,"strategy.write");UUID objectiveId=uuid(k.get("objective_id"));jdbc.sql("update strategic_key_results set current_value=:value,status=:status,updated_by_subject=:actor,updated_at=current_timestamp where company_id=:companyId and id=:id").param("value",request.currentValue()).param("status",request.status()).param("actor",authentication.getName()).param("companyId",companyId.toString()).param("id",keyResultId.toString()).update();recompute(objectiveId);audit.write(companyId,authentication.getName(),"KEY_RESULT_PROGRESS_UPDATED","STRATEGIC_KEY_RESULT",keyResultId.toString(),"{}");return new CreatedResource(keyResultId,request.status());}
    @Transactional public CreatedResource setObjectiveStatus(UUID companyId,UUID objectiveId,StatusRequest request,Authentication authentication){Map<String,Object>o=objective(companyId,objectiveId,authentication,"strategy.write");jdbc.sql("update strategic_objectives set status=:status,updated_at=current_timestamp where company_id=:companyId and id=:id").param("status",request.status()).param("companyId",companyId.toString()).param("id",objectiveId.toString()).update();audit.write(companyId,authentication.getName(),"STRATEGIC_OBJECTIVE_"+request.status(),"STRATEGIC_OBJECTIVE",objectiveId.toString(),"{}");return new CreatedResource(objectiveId,request.status());}

    public List<Map<String,Object>> snapshots(UUID companyId,Authentication authentication){if(!access.hasGlobalAccess(authentication,companyId,"reporting.read"))return List.of();return rows("select id,name,report_type,scope_type,scope_id,period_start,period_end,generated_by_subject,generated_at from management_report_snapshots where company_id=:companyId order by generated_at desc limit 100",map(companyId));}
    public Map<String,Object> snapshot(UUID companyId,UUID snapshotId,Authentication authentication){if(!access.hasGlobalAccess(authentication,companyId,"reporting.read"))forbidden();return one("select id,name,report_type,scope_type,scope_id,period_start,period_end,data_json::text data_json,generated_by_subject,generated_at from management_report_snapshots where company_id=:companyId and id=:id",map(companyId,"id",snapshotId));}
    @Transactional public CreatedResource createSnapshot(UUID companyId,SnapshotRequest request,Authentication authentication){if(!access.hasGlobalAccess(authentication,companyId,"reporting.manage"))forbidden();if(request.periodEnd().isBefore(request.periodStart()))bad("Report period end must be on or after start");ExecutiveSummary summary=summaryForPeriod(companyId,authentication,request.periodStart(),request.periodEnd());Map<String,Object>data=new LinkedHashMap<>();data.put("summary",summary);data.put("trends",trends(companyId,authentication));data.put("projectHealth",projectHealth(companyId,authentication));data.put("objectives",objectives(companyId,authentication));UUID id=UUID.randomUUID();String payload=json.writeValueAsString(data);jdbc.sql("insert into management_report_snapshots(id,company_id,name,report_type,scope_type,scope_id,period_start,period_end,data_json,generated_by_subject) values(:id,:companyId,:name,:type,'COMPANY',:companyId,:start,:end,cast(:data as jsonb),:actor)").param("id",id.toString()).param("companyId",companyId.toString()).param("name",request.name()).param("type",request.reportType()).param("start",request.periodStart()).param("end",request.periodEnd()).param("data",payload).param("actor",authentication.getName()).update();audit.write(companyId,authentication.getName(),"MANAGEMENT_REPORT_SNAPSHOT_CREATED","MANAGEMENT_REPORT_SNAPSHOT",id.toString(),"{}");return new CreatedResource(id,"READY");}
    public String exportCsv(UUID companyId,Authentication authentication){if(!access.hasGlobalAccess(authentication,companyId,"reporting.export"))forbidden();ExecutiveSummary s=summary(companyId,authentication);String currency=safeCsv(s.currency());return "metric,value,currency\r\nactive_employees,"+s.activeEmployees()+",\r\nactive_projects,"+s.activeProjects()+",\r\noverdue_tasks,"+s.overdueTasks()+",\r\nrevenue,"+s.revenue()+","+currency+"\r\nexpenses,"+s.expenses()+","+currency+"\r\nprofit,"+s.profit()+","+currency+"\r\nopen_pipeline,"+s.openPipeline()+","+currency+"\r\noverdue_receivables,"+s.overdueReceivables()+","+currency+"\r\npending_approvals,"+s.pendingApprovals()+",\r\nlow_stock_items,"+s.lowStockItems()+",\r\nobjectives_at_risk,"+s.objectivesAtRisk()+",\r\n";}

    private Map<String,Object>objective(UUID companyId,UUID id,Authentication auth,String permission){Map<String,Object>o=one("select id,scope_type,scope_id,owner_subject from strategic_objectives where company_id=:companyId and id=:id",map(companyId,"id",id));ensureScope(o,companyId,auth,permission);return o;}
    private void ensureScope(Map<String,Object>row,UUID companyId,Authentication auth,String permission){if(auth.getName().equals(text(row.get("owner_subject")))){if(access.canAccess(auth,companyId,permission))return;}if(!access.canAccessScope(auth,companyId,text(row.get("scope_type")),uuid(row.get("scope_id")),permission))forbidden();}
    private void validateScope(UUID companyId,String type,UUID id){String table=switch(type){case"COMPANY"->"companies";case"DEPARTMENT"->"departments";case"PROJECT"->"pm_projects";default->throw new IllegalArgumentException();};long count=jdbc.sql("select count(*) from "+table+" where id=:id"+("COMPANY".equals(type)?"":" and company_id=:companyId")).param("id",id.toString()).params("COMPANY".equals(type)?Map.of():Map.of("companyId",companyId.toString())).query(Long.class).single();if(count==0)notFound("Reporting scope not found");if("COMPANY".equals(type)&&!id.equals(companyId))notFound("Reporting scope not found");}
    private void activeMember(UUID companyId,String subject){if(jdbc.sql("select count(*) from company_memberships where company_id=:companyId and keycloak_subject=:subject and status='ACTIVE'").param("companyId",companyId.toString()).param("subject",subject).query(Long.class).single()==0)bad("Objective owner must be an active company member");}
    private void recompute(UUID objectiveId){List<Map<String,Object>>keys=jdbc.sql("select baseline_value,target_value,current_value,weight from strategic_key_results where objective_id=:id").param("id",objectiveId.toString()).query().listOfRows();BigDecimal weighted=BigDecimal.ZERO,total=BigDecimal.ZERO;for(Map<String,Object>k:keys){BigDecimal baseline=decimal(k.get("baseline_value")),target=decimal(k.get("target_value")),current=decimal(k.get("current_value")),weight=decimal(k.get("weight"));BigDecimal progress=current.subtract(baseline).divide(target.subtract(baseline),8,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)).max(BigDecimal.ZERO).min(BigDecimal.valueOf(100));weighted=weighted.add(progress.multiply(weight));total=total.add(weight);}BigDecimal progress=total.signum()==0?BigDecimal.ZERO:weighted.divide(total,2,RoundingMode.HALF_UP);jdbc.sql("update strategic_objectives set progress_percent=:progress,updated_at=current_timestamp where id=:id").param("progress",progress).param("id",objectiveId.toString()).update();}
    private Map<String,Object>params(UUID companyId,Authentication auth,String permission){Map<String,Object>p=map(companyId);p.put("subject",auth.getName());p.put("global",access.hasGlobalAccess(auth,companyId,permission));return p;}
    private Map<String,Object>map(UUID companyId,Object...pairs){Map<String,Object>p=new LinkedHashMap<>();p.put("companyId",companyId.toString());for(int i=0;i<pairs.length;i+=2)p.put(String.valueOf(pairs[i]),pairs[i+1] instanceof UUID u?u.toString():pairs[i+1]);return p;}
    private long count(String sql,Map<String,Object>p){return named.queryForObject(sql,p,Long.class);}private List<Map<String,Object>>rows(String sql,Map<String,Object>p){return named.queryForList(sql,p);}private Map<String,Object>one(String sql,Map<String,Object>p){List<Map<String,Object>>r=rows(sql,p);if(r.isEmpty())notFound("Reporting record not found");return r.getFirst();}
    private static BigDecimal decimal(Object value){return value==null?BigDecimal.ZERO:new BigDecimal(value.toString());}private static long number(Object value){return value==null?0:Long.parseLong(value.toString());}private static UUID uuid(Object value){return UUID.fromString(value.toString().trim());}private static String text(Object value){return value==null?"":value.toString();}private static String blank(String value){return value==null||value.isBlank()?null:value.trim();}private static String safeCsv(String value){return value.matches("^[=+@-].*")?"'"+value:value;}private static void bad(String message){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private static void forbidden(){throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Reporting scope is not allowed");}private static ResponseStatusException notFound(String message){return new ResponseStatusException(HttpStatus.NOT_FOUND,message);}
}
